"""Apply the v1.1.0 cluster update to the published v1.0.0 checkout."""
import base64
import hashlib
import json
import zlib
from pathlib import Path

PAYLOAD = """"""
root = Path.cwd()
bundle = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
manifest = root / "custom_components/scottibyte_incus/manifest.json"
if not manifest.exists():
    raise SystemExit("Run this script from your ha-scottibyte-incus checkout.")
version = json.loads(manifest.read_text())["version"]
if version not in ("1.0.0", "1.1.0"):
    raise SystemExit(f"Expected version 1.0.0 or 1.1.0, found {version}; no files modified.")
for name, expected in bundle["expected"].items():
    current = (root / name).read_text().rstrip()
    if current != bundle["files"][name].rstrip() and hashlib.sha256(current.encode()).hexdigest() != expected:
        raise SystemExit(f"Unexpected local changes in {name}; no files modified.")
for name, content in bundle["files"].items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
print("Cluster member enrollment, member cards and endpoint selection applied; version 1.1.0.")
